-- Phase 07 AI knowledge and Facebook organic/paid many-to-many mapping
CREATE TABLE IF NOT EXISTS product_ai_knowledge(product_code TEXT PRIMARY KEY REFERENCES products(product_code),specifications_json TEXT NOT NULL DEFAULT '{}',faq_json TEXT NOT NULL DEFAULT '[]',sales_instructions TEXT NOT NULL DEFAULT '',escalation_rules TEXT NOT NULL DEFAULT '',verified_information TEXT NOT NULL DEFAULT '',prohibited_claims TEXT NOT NULL DEFAULT '',features TEXT NOT NULL DEFAULT '',package_contents TEXT NOT NULL DEFAULT '',delivery_policy TEXT NOT NULL DEFAULT '',payment_methods TEXT NOT NULL DEFAULT '',warranty_policy TEXT NOT NULL DEFAULT '',return_policy TEXT NOT NULL DEFAULT '',approval_status TEXT NOT NULL DEFAULT 'draft' CHECK(approval_status IN ('draft','review','approved','published')),version INTEGER NOT NULL DEFAULT 1,approved_by TEXT,approved_at TEXT,published_at TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS facebook_contents(id INTEGER PRIMARY KEY AUTOINCREMENT,page_id TEXT NOT NULL,facebook_content_id TEXT NOT NULL,content_type TEXT NOT NULL DEFAULT 'post',content_name TEXT,post_message TEXT,permalink TEXT,source TEXT NOT NULL DEFAULT 'manual',sync_status TEXT NOT NULL DEFAULT 'unmapped',status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(page_id,facebook_content_id));
CREATE TABLE IF NOT EXISTS facebook_content_products(content_id INTEGER NOT NULL REFERENCES facebook_contents(id),product_code TEXT NOT NULL REFERENCES products(product_code),is_primary INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(content_id,product_code));
CREATE TABLE IF NOT EXISTS facebook_content_aliases(alias_type TEXT NOT NULL,alias_id TEXT NOT NULL,content_id INTEGER NOT NULL REFERENCES facebook_contents(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(alias_type,alias_id));
CREATE TABLE IF NOT EXISTS facebook_sync_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TEXT,status TEXT NOT NULL DEFAULT 'running',imported INTEGER NOT NULL DEFAULT 0,updated INTEGER NOT NULL DEFAULT 0,error_code TEXT);
CREATE INDEX IF NOT EXISTS idx_facebook_content_product_code ON facebook_content_products(product_code);
CREATE INDEX IF NOT EXISTS idx_facebook_contents_status ON facebook_contents(status,sync_status);
